const crypto = require('crypto');

// Function to generate salt and hash password
function hashPassword(password) {
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.createHash('sha512').update(salt + password).digest('hex');
    return { salt, hash };
}

// Example usage:
const password = "userpassword";
const { salt, hash } = hashPassword(password);
console.log("Salt:", salt);
console.log("Hashed Password:", hash);

// To verify a password
function verifyPassword(storedSalt, storedHash, providedPassword) {
    const newHash = crypto.createHash('sha512').update(storedSalt + providedPassword).digest('hex');
    return storedHash === newHash;
}

const isValid = verifyPassword(salt, hash, password);
console.log("Password Valid:", isValid);

